// Machine loop wiring for THIS repository (see dmtools-agents
// docs/machine-factory-integration.md §5a). The factory resolves leg →
// runner here; runner paths are repo-relative. bug/story may share a
// single 'dev' entry instead of two.
module.exports = {
  // #687: whose login is "the machine" — auto rework (prMachineAuthor)
  // and pr_approved arming fire only on PRs authored by this login.
  machineAuthor: 'ai-teammate',
  sm: {
    runners: {
      bug: '.dmtools/runners/fa-bug-dev.json',
      story: '.dmtools/runners/fa-story-dev.json',
      review: '.dmtools/runners/fa-review.json',
      rework: '.dmtools/runners/fa-rework.json'
    }
  }
};
----
{
  "parent": {
    "path": "pr_review@latest"
  },
  "merge": [
    "params.cliPrompts"
  ],
  "params": {
    "envVariables": {
      "AI_AGENT_PROVIDER": "fa",
      "FA_PROVIDER_TYPE": "copilot",
      "FA_PROVIDER_CONFIG": "{\"baseUrl\":\"https://api.enterprise.githubcopilot.com\",\"model\":\"claude-sonnet-5.5\",\"apiKeyEnvVar\":\"COPILOT_EPAM_KEY\",\"input\":[\"text\",\"image\"]}",
      "FA_PROVIDERS_QUEUE": "[{\"provider_type\":\"copilot\",\"provider_config\":{\"baseUrl\":\"https://api.enterprise.githubcopilot.com\",\"model\":\"claude-haiku-5.5\",\"apiKeyEnv\":\"COPILOT_EPAM_KEY\",\"input\":[\"text\",\"image\"]}},{\"provider_type\":\"openai-completions\",\"provider_config\":{\"baseUrl\":\"https://api.kimi.com/coding/v1\",\"model\":\"kimi-for-coding\",\"apiKeyEnv\":\"KIMI_REVIEW_KEY\",\"input\":[\"text\",\"image\"]}},{\"provider_type\":\"zai\",\"provider_config\":{\"baseUrl\":\"https://api.z.ai/api/coding/paas/v4\",\"model\":\"glm-5.3-flash\",\"apiKeyEnv\":\"ZAI_CODE_KEY\",\"input\":[\"text\",\"image\"]}}]"
    },
    "inputJql": "",
    "customParams": {
      "allowApproveWithSuggestions": true,
      "formalGithubReview": true
    },
    "cliPrompts": [
      "pack:instructions/pr_review/review_verdict_rules.md"
    ]
  }
}
----
{
  "parent": {
    "path": "pr_rework@latest"
  },
  "params": {
    "envVariables": {
      "DEFAULT_TRACKER": "github",
      "AI_AGENT_PROVIDER": "fa",
      "FA_PROVIDER_TYPE": "zai",
      "FA_PROVIDER_CONFIG": "{\"baseUrl\":\"https://api.z.ai/api/coding/paas/v4\",\"model\":\"glm-5.3-flash\",\"apiKeyEnvVar\":\"ZAI_CODE_KEY\",\"input\":[\"text\",\"image\"]}",
      "FA_PROVIDERS_QUEUE": "[{\"provider_type\":\"copilot\",\"provider_config\":{\"baseUrl\":\"https://api.enterprise.githubcopilot.com\",\"model\":\"claude-haiku-5.5\",\"apiKeyEnv\":\"COPILOT_EPAM_KEY\",\"input\":[\"text\",\"image\"]}},{\"provider_type\":\"openai-completions\",\"provider_config\":{\"baseUrl\":\"https://api.kimi.com/coding/v1\",\"model\":\"kimi-for-coding\",\"apiKeyEnv\":\"KIMI_REVIEW_KEY\",\"input\":[\"text\",\"image\"]}},{\"provider_type\":\"zai\",\"provider_config\":{\"baseUrl\":\"https://api.z.ai/api/coding/paas/v4\",\"model\":\"glm-5.3-flash\",\"apiKeyEnv\":\"ZAI_CODE_KEY\",\"input\":[\"text\",\"image\"]}}]"
    },
    "inputJql": "",
    "cliPromptsByTracker": {
      "github": [
        "pack:instructions/common/github_comment_format.md"
      ]
    },
    "customParams": {
      "targetRepository": {
        "workingDir": ".",
        "baseBranch": "main"
      }
    }
  }
}
